 if(t==="environment/run"){hasE=true;envRuns++;if(o.data.heldOut)heldOut++;const im=o.data.implementer??"route(absent)";impl[im]=(impl[im]||0)+1;if(im==="route"||im==="route(absent)")isRoute=true;const m=o.data.model?o.data.model.provider+"/"+o.data.model.model:"(none)";models[m]=(models[m]||0)+1}
}
if(hasA)withAssistant++;if(hasC)withCert++;if(hasT)withTerms++;if(hasE)withEnv++;if(hasA&&hasE&&isRoute)routeWithAssistant++;}
