const sel={};for(const k of key)sel[k]=types[k]||0;console.log("event-type counts:",sel);
const logical=Object.entries(types).filter(([k])=>k!=="session").reduce((a,[,v])=>a+v,0);console.log("non-header rows:",logical,"distinct row types:",Object.keys(types).length);
console.log("dataUse agreements (event count):",agreements);console.log("verification/run verdicts:",verdicts);console.log("environment/run implementer:",impl);console.log("environment/run model route:",models);
}'

